package com.binaris.wizardry.setup.registries.client;

import com.binaris.wizardry.api.content.DeferredObject;
import com.binaris.wizardry.client.renderer.blockentity.ArcaneWorkbenchRender;
import com.binaris.wizardry.client.renderer.blockentity.BookshelfRenderer;
import com.binaris.wizardry.client.renderer.blockentity.ImbuementAltarRenderer;
import com.binaris.wizardry.setup.registries.EBBlockEntities;
import com.google.common.collect.Maps;
import net.minecraft.client.renderer.blockentity.BlockEntityRendererProvider;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.entity.BlockEntityType;

import java.util.Map;
import java.util.function.BiConsumer;

/**
 * Handles the registration of block entity renderers. Check {@code EBBlockEntities}
 */
public final class EBBlockEntityRenderers {
    private static final Map<DeferredObject<? extends BlockEntityType<? extends BlockEntity>>, BlockEntityRendererProvider<?>> providers = Maps.newHashMap();

    private EBBlockEntityRenderers() {
    }

    public static void init() {
        registerBlockEntityRenderer(EBBlockEntities.ARCANE_WORKBENCH, ArcaneWorkbenchRender::new);
        registerBlockEntityRenderer(EBBlockEntities.IMBUEMENT_ALTAR, ImbuementAltarRenderer::new);
        registerBlockEntityRenderer(EBBlockEntities.BOOKSHELF, BookshelfRenderer::new);
    }

    private static <T extends BlockEntity> void registerBlockEntityRenderer(
            DeferredObject<? extends BlockEntityType<T>> blockEntityType,
            BlockEntityRendererProvider<T> provider) {
        providers.put(blockEntityType, provider);
    }

    @SuppressWarnings("unchecked")
    public static void register(BiConsumer<BlockEntityType<? extends BlockEntity>, BlockEntityRendererProvider<BlockEntity>> consumer) {
        providers.forEach((blockEntityType, provider) ->
                consumer.accept(blockEntityType.get(), (BlockEntityRendererProvider<BlockEntity>) provider));
    }
}

package com.binaris.wizardry.setup.registries.client;

import com.binaris.wizardry.api.content.data.ConjureData;
import com.binaris.wizardry.api.content.spell.SpellAction;
import com.binaris.wizardry.api.content.util.CastItemDataHelper;
import com.binaris.wizardry.core.mixin.accessor.ItemPropertiesAccessor;
import com.binaris.wizardry.core.platform.Services;
import com.binaris.wizardry.setup.datagen.EBDataGenProcessor;
import com.binaris.wizardry.setup.registries.EBItems;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.item.Item;

public final class EBItemProperties {
    private EBItemProperties() {
    }

    public static void register() {
        EBDataGenProcessor.wandItems().forEach((s, i) ->
                registerWandProperties(i.get()));

        // Other items with pulling/conjure properties
        pullingItem(EBItems.FLAMECATCHER.get());
        conjureItem(EBItems.FLAMECATCHER.get());

        conjureItem(EBItems.FROST_AXE.get());
        conjureItem(EBItems.FLAMING_AXE.get());

        conjureItem(EBItems.SPECTRAL_PICKAXE.get());

        pullingItem(EBItems.SPECTRAL_BOW.get());
        conjureItem(EBItems.SPECTRAL_BOW.get());
    }

    private static void registerWandProperties(Item wand) {
        ItemPropertiesAccessor.callRegister(wand, new ResourceLocation("pointing"), (stack, clientLevel, entity, seed) ->
                entity != null && entity.isUsingItem() && entity.getUseItem() == stack
                        && isPointingAction(CastItemDataHelper.getCurrentSpell(stack).getAction()) ? 1.0F : 0.0F);

        // Kept for backwards compatibility with models and addons that still use the old 'casting' property.
        ItemPropertiesAccessor.callRegister(wand, new ResourceLocation("casting"), (stack, clientLevel, entity, seed) ->
                entity != null && entity.isUsingItem() && entity.getUseItem() == stack ? 1.0F : 0.0F);
    }

    private static boolean isPointingAction(SpellAction action) {
        return action == SpellAction.POINT
                || action == SpellAction.POINT_UP
                || action == SpellAction.POINT_DOWN
                || action == SpellAction.GRAPPLE
                || action == SpellAction.SUMMON
                || action == SpellAction.THRUST
                || action == SpellAction.IMBUE;
    }

    private static void pullingItem(Item item) {
        ItemPropertiesAccessor.callRegister(item, new ResourceLocation("pull"), (stack, clientLevel, entity, seed) -> {
            if (entity == null) {
                return 0.0F;
            } else {
                return entity.getUseItem() != stack ? 0.0F : (float) (stack.getUseDuration() - entity.getUseItemRemainingTicks()) / 20.0F;
            }
        });

        ItemPropertiesAccessor.callRegister(item, new ResourceLocation("pulling"), (stack, clientLevel, entity, seed) ->
                entity != null && entity.isUsingItem() && entity.getUseItem() == stack ? 1.0F : 0.0F);

    }

    private static void conjureItem(Item item) {
        ItemPropertiesAccessor.callRegister(item, new ResourceLocation("conjure"), (stack, clientLevel, entity, seed) -> {
            ConjureData data = Services.OBJECT_DATA.getConjureData(stack);
            if (data != null && data.isSummoned()) {
                int frames = 8;
                int remaining = data.getRemainingLifetime(clientLevel.getGameTime());
                int duration = data.getDuration();
                int elapsed = duration - remaining;
                return elapsed < frames ? (float) elapsed / frames : (float) remaining / frames;
            }
            return 0.0F;
        });

        ItemPropertiesAccessor.callRegister(item, new ResourceLocation("conjuring"), (stack, clientLevel, entity, seed) -> {
            ConjureData data = Services.OBJECT_DATA.getConjureData(stack);
            if (data != null && data.isSummoned()) {
                int frames = 8;
                int remaining = data.getRemainingLifetime(clientLevel.getGameTime());
                int duration = data.getDuration();
                int elapsed = duration - remaining;
                return elapsed < frames || remaining < frames ? 1.0F : 0.0F;
            }
            return 0.0F;
        });
    }


}

package com.binaris.wizardry.setup.registries.client;

import com.binaris.wizardry.WizardryMainMod;
import com.binaris.wizardry.api.content.event.EBClientTickEvent;
import com.binaris.wizardry.api.content.item.ICastItem;
import com.binaris.wizardry.api.content.util.EntityUtil;
import com.binaris.wizardry.api.content.util.CastItemDataHelper;
import com.binaris.wizardry.client.SpellGUIDisplay;
import com.binaris.wizardry.content.item.WandItem;
import com.binaris.wizardry.core.config.EBServerConfig;
import com.binaris.wizardry.core.networking.c2s.ControlInputPacketC2S;
import com.binaris.wizardry.core.networking.c2s.SpellAccessPacketC2S;
import com.binaris.wizardry.core.platform.Services;
import com.binaris.wizardry.setup.registries.EBSounds;
import com.mojang.blaze3d.platform.InputConstants;
import net.minecraft.client.KeyMapping;
import net.minecraft.client.Minecraft;
import net.minecraft.client.resources.sounds.SimpleSoundInstance;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import org.lwjgl.glfw.GLFW;

import java.util.stream.IntStream;

public final class EBKeyBinding {
    public static final String CATEGORY = "key.categories." + WizardryMainMod.MOD_ID;

    public static final KeyMapping NEXT_SPELL = new KeyMapping("key." + WizardryMainMod.MOD_ID + ".next_spell", InputConstants.Type.KEYSYM, InputConstants.KEY_N, CATEGORY);
    public static final KeyMapping PREVIOUS_SPELL = new KeyMapping("key." + WizardryMainMod.MOD_ID + ".previous_spell", InputConstants.Type.KEYSYM, InputConstants.KEY_B, CATEGORY);
    public static final KeyMapping[] SPELL_QUICK_ACCESS = new KeyMapping[WandItem.BASE_SPELL_SLOTS + EBServerConfig.UPGRADE_STACK_LIMIT.get()];

    static boolean nextSpellKeyPressed = false;
    static boolean previousSpellKeyPressed = false;
    static boolean[] quickAccessKeyPressed = new boolean[SPELL_QUICK_ACCESS.length];

    static {
        IntStream.range(0, SPELL_QUICK_ACCESS.length).forEach(i -> SPELL_QUICK_ACCESS[i]
                = new KeyMapping("key." + WizardryMainMod.MOD_ID + ".spell_" + (i + 1), InputConstants.Type.KEYSYM, GLFW.GLFW_KEY_UNKNOWN, CATEGORY));
    }

    private EBKeyBinding() {
    }

    public static void onClientTick(EBClientTickEvent event) {
        Player player = event.getMinecraft().player;
        if (player == null) return;

        ItemStack wand = EntityUtil.getWandInUse(player);
        if (wand.isEmpty()) return;

        if (NEXT_SPELL.isDown() && Minecraft.getInstance().mouseHandler.isMouseGrabbed()) {
            if (!nextSpellKeyPressed) {
                nextSpellKeyPressed = true;
                selectNextSpell(wand);
            }
        } else {
            nextSpellKeyPressed = false;
        }

        if (PREVIOUS_SPELL.isDown() && Minecraft.getInstance().mouseHandler.isMouseGrabbed()) {
            if (!previousSpellKeyPressed) {
                previousSpellKeyPressed = true;
                selectPreviousSpell(wand);
            }
        } else {
            previousSpellKeyPressed = false;
        }

        for (int i = 0; i < SPELL_QUICK_ACCESS.length; i++) {
            if (SPELL_QUICK_ACCESS[i].isDown() && Minecraft.getInstance().mouseHandler.isMouseGrabbed()) {
                if (!quickAccessKeyPressed[i]) {
                    quickAccessKeyPressed[i] = true;
                    selectSpell(wand, i);
                }
            } else {
                quickAccessKeyPressed[i] = false;
            }
        }
    }

    public static void selectNextSpell(ItemStack wand) {
        ICastItem item = (ICastItem) wand.getItem();

        ControlInputPacketC2S msg = new ControlInputPacketC2S(ControlInputPacketC2S.ControlType.NEXT_SPELL_KEY);
        Services.NETWORK_HELPER.sendToServer(msg);
        if (Services.PLATFORM.getPlatformName().equals("Fabric")) item.selectNextSpell(wand);
        SpellGUIDisplay.playSpellSwitchAnimation(true);

        Minecraft.getInstance().getSoundManager().play(SimpleSoundInstance.forUI(EBSounds.ITEM_WAND_SWITCH_SPELL.get(), 1));
    }

    public static void selectPreviousSpell(ItemStack wand) {
        ICastItem item = (ICastItem) wand.getItem();

        ControlInputPacketC2S msg = new ControlInputPacketC2S(ControlInputPacketC2S.ControlType.PREVIOUS_SPELL_KEY);
        Services.NETWORK_HELPER.sendToServer(msg);
        if (Services.PLATFORM.getPlatformName().equals("Fabric")) item.selectPreviousSpell(wand);
        SpellGUIDisplay.playSpellSwitchAnimation(false);

        Minecraft.getInstance().getSoundManager().play(SimpleSoundInstance.forUI(EBSounds.ITEM_WAND_SWITCH_SPELL.get(), 1));
    }

    private static void selectSpell(ItemStack wand, int index) {
        ICastItem item = (ICastItem) wand.getItem();
        int currentIndex = CastItemDataHelper.getCurrentSpellIndex(wand);
        if (index == currentIndex) return;

        if (item.selectSpell(wand, index)) {
            SpellAccessPacketC2S msg = new SpellAccessPacketC2S(index);
            Services.NETWORK_HELPER.sendToServer(msg);

            SpellGUIDisplay.playSpellSwitchAnimation(true);
            Minecraft.getInstance().getSoundManager().play(SimpleSoundInstance.forUI(EBSounds.ITEM_WAND_SWITCH_SPELL.get(), 1));
        }
    }
}

package com.binaris.wizardry.setup.registries.client;

import com.binaris.wizardry.api.content.DeferredObject;
import com.binaris.wizardry.client.gui.screens.ArcaneWorkbenchScreen;
import com.binaris.wizardry.client.gui.screens.BookshelfScreen;
import com.binaris.wizardry.setup.registries.EBMenus;
import com.google.common.collect.Maps;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;
import net.minecraft.client.gui.screens.inventory.MenuAccess;
import net.minecraft.network.chat.Component;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.inventory.MenuType;

import java.util.Map;
import java.util.function.BiConsumer;

/**
 * Handles the registration of menu screens. Check {@code EBMenus}
 */
public final class EBMenuScreens {
    private static final Map<DeferredObject<? extends MenuType<? extends AbstractContainerMenu>>, ScreenFactory<?, ?>> screens = Maps.newHashMap();

    private EBMenuScreens() {
    }

    public static void init() {
        registerScreen(EBMenus.ARCANE_WORKBENCH_MENU, ArcaneWorkbenchScreen::new);
        registerScreen(EBMenus.BOOKSHELF_MENU, BookshelfScreen::new);
    }

    private static <M extends AbstractContainerMenu, U extends Screen & MenuAccess<M>> void registerScreen(
            DeferredObject<? extends MenuType<M>> menuType,
            ScreenFactory<M, U> screenFactory) {
        screens.put(menuType, screenFactory);
    }

    @SuppressWarnings("unchecked")
    public static void register(BiConsumer<MenuType<? extends AbstractContainerMenu>, ScreenFactory<AbstractContainerMenu, AbstractContainerScreen<AbstractContainerMenu>>> consumer) {
        screens.forEach((menuType, screenFactory) ->
                consumer.accept(menuType.get(), (ScreenFactory<AbstractContainerMenu, AbstractContainerScreen<AbstractContainerMenu>>) screenFactory));
    }

    @FunctionalInterface
    public interface ScreenFactory<T extends AbstractContainerMenu, U extends Screen & MenuAccess<T>> {
        U create(T menu, Inventory inventory, Component title);
    }
}

package com.binaris.wizardry.setup.registries.client;

import com.binaris.wizardry.api.client.particle.ParticleWizardry;
import com.binaris.wizardry.api.content.DeferredObject;
